}

private static boolean canTravelMazeUtil(int start, int end, int[][] paths, boolean[] visited, boolean[] path) {
    if (start == end) {
        return true;
    }
    if (visited[start]) {
        return false;
    }
    visited[start] = true;
    path[start] = true;
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == start && !path[paths[i][1]]) {
            if (canTravelMazeUtil(paths[i][1], end, paths, visited, path)) {
                return true;
            }
        } else if (paths[i][1] == start && !path[paths[i][0]]) {
            if (canTravelMazeUtil(paths[i][0], end, paths, visited, path)) {
                return true;
            }
        }
    }
    path[start] = false;
    return false;
}

