public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i == 0) continue;
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            int lastDigit = num % 10;

            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    if (nextNum >= low) {
                        result.add(nextNum);
                    }
                    queue.offer(nextNum);
                }
            }

            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    if (nextNum >= low) {
                        result.add(nextNum);
                    }
                    queue.offer(nextNum);
                }
            }
        }

        Collections.sort(result);
        return result;
    }

public static int countDigitOne(int n) {
    int count = 0;
    for (long i = 1; i <= n; i *= 10) {
        long divider = i * 10;
        long higher = n / divider;
        long current = (n / i) % 10;
        long lower = n % i;

        if (current == 0) {
            count += higher * i;
        } else if (current == 1) {
            count += higher * i + lower + 1;
        } else {
            count += (higher + 1) * i;
        }
    }
    return count;
}

