public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    boolean[] visited = new boolean[n];
    int count = 0;

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            count += dfs(A, visited, i, 1, A[i]);
        }
    }

    return count;
}

private static int dfs(int[] A, boolean[] visited, int index, int length, int prev) {
    if (length == A.length) return 1;

    int count = 0;
    visited[index] = true;

    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(prev + A[i])) {
            count += dfs(A, visited, i, length + 1, A[i]);
        }
    }

    visited[index] = false;
    return count;
}

private static boolean isPerfectSquare(int num) {
